Web kamerası izinlerini ve gizlilik haklarını test etmek için bir komut dosyası oluşturmak, kullanıcıların cihazlarındaki kamera erişimiyle ilgili bilgileri toplamak ve doğrulamak için JavaScript ve tarayıcı API'lerini kullanabilir. Aşağıda, bu amaçla kullanabileceğiniz bir örnek JavaScript komut dosyası verilmiştir:

```javascript
// Web Kamerası İzinlerini Test Etme

// Kullanıcıdan izin isteme
async function requestCameraPermission() {
    const stream = await navigator.mediaDevices.getUserMedia({ video: true });
    try {
        // İzin verildi, akışı kullanabilirsin
        console.log("Kamera izni verildi!");
        return stream;
    } catch (error) {
        console.error("Kamera izni reddedildi veya hata:", error);
        return null;
    } finally {
        // Akışı serbest bırak (özellikle hata durumunda)
        if (stream) {
            stream.getTracks().forEach(track => track.stop());
        }
    }
}

// Mevcut Kamera İzinlerini Kontrol Etme
function checkCameraPermissions() {
    navigator.mediaDevices.getPermissions().then(permissions => {
        const cameraPermission = permissions.find(permission => permission.kind === 'camera');
        if (cameraPermission && cameraPermission.state === 'granted') {
            console.log("Kamera izni verilmiş.");
        } else {
            console.log("Kamera izni verilmemiş veya belirsiz.");
        }
    });
}

// Gizlilik Bildirimi ve Kullanıcı Onayı
function showPrivacyNotice() {
    alert("Bu komut dosyası, web kameranızın izinlerini test etmek ve gizlilik haklarınızı kontrol etmek için tasarlanmıştır. Verilerinizin güvenliği ve gizliliği önemlidir. İzinleri kabul ettiğinizden emin olun.");
}

// Ana Fonksiyon
async function main() {
    showPrivacyNotice();

    // Kullanıcıdan izin isteme
    const cameraStream = await requestCameraPermission();

    if (cameraStream) {
        // Kamera akışını kullanmak için ek kodlar buraya eklenebilir
        // Örneğin, bir video öğesine akış bağlama veya görüntüleme
        console.log("Kamera akışı başarıyla başlatıldı.");
    } else {
        console.log("Kamera izni verilemedi.");
    }

    checkCameraPermissions();
}

